  var expected=EXEC[kind](input);
  var ctx=traceCtx(input,expected);
  var desc=fmt(P1[kind],ctx)+'\n\n'+fmt(P2[kind],ctx)+'\n\n'+fmt(P3[kind],ctx);
  var prog=PYPROG[kind].split('@@INPUT@@').join(JSON.stringify(input));
  var r={
    id:PREFIX+String(seed).padStart(6,'0'),
    title:'Trace drill: '+TRACE_TITLES[kind]+' — '+NAME,
    description:desc,
    ladder:2,group:TRACE_GROUP,
    method:kind,
    test:{input:input,expected:expected},
    program:prog,language:'python',
    complexity_notes:'Drill answer computed by the reference implementation; validate() recomputes it independently.',
    src:GEN_SRC,last_verified:'2026-10-19'
  };
  if(SIG){r.creation_mode='SIGNATURE-GENERATED';}
  else{r.sample=true;}
  r.disclaimer=GEN_DISCLAIMER;
  return r;
